import numpy as np, random, json, sys, time
from fasteval import *

LAM = 1.0e6


class Opt:
    def __init__(self, f, vm=0.97, dm=0.536, bm=0.97, cm=0.95, vfac=1.03):
        self.f = f
        self.kw = dict(vm=vm, dm=dm, bm=bm, cm=cm, vfac=vfac)
        self.cache = {}
        self.nevals = 0

    def key(self, deck, chord):
        return tuple(deck[z] for z in ZLIST) + tuple(chord[c] for c in CLIST)

    def J(self, deck, chord):
        k = self.key(deck, chord)
        if k not in self.cache:
            o = self.f.evaluate(deck, chord, **self.kw)
            self.nevals += 1
            self.cache[k] = (o['total'] + LAM * o['viol'], o['total'], o['viol'])
        return self.cache[k]

    def neighbours(self, deck, chord):
        types = set(deck.values())
        for z in ZLIST:
            for t in DECK_LIST:
                if t == deck[z]:
                    continue
                nt = set(deck[zz] for zz in ZLIST if zz != z) | {t}
                if len(nt) > 4:
                    continue
                d2 = dict(deck); d2[z] = t
                yield d2, chord
        for c in CLIST:
            i = SEC_LIST.index(chord[c])
            for di in (-2, -1, 1, 2):
                j = i + di
                if 0 <= j < len(SEC_LIST):
                    c2 = dict(chord); c2[c] = SEC_LIST[j]
                    yield deck, c2

    def descend(self, deck, chord, verbose=False):
        cur = self.J(deck, chord)
        while True:
            best = None
            for d2, c2 in self.neighbours(deck, chord):
                j = self.J(d2, c2)
                if j[0] < cur[0] - 1e-6 and (best is None or j[0] < best[0][0]):
                    best = (j, d2, c2)
            if best is None:
                return deck, chord, cur
            cur, deck, chord = best
            if verbose:
                print('  J=%.0f cost=%.0f viol=%.4f' % cur, flush=True)

    def perturb(self, deck, chord, k=3):
        deck = dict(deck); chord = dict(chord)
        types = list(set(deck.values()))
        for _ in range(k):
            if random.random() < 0.75:
                z = random.choice(ZLIST)
                if random.random() < 0.5 and len(types) >= 1:
                    deck[z] = random.choice(types)
                else:
                    i = DECK_LIST.index(deck[z])
                    deck[z] = DECK_LIST[max(0, min(len(DECK_LIST) - 1, i + random.choice([-3, -2, -1, 1, 2, 3])))]
            else:
                c = random.choice(CLIST)
                i = SEC_LIST.index(chord[c])
                chord[c] = SEC_LIST[max(0, min(len(SEC_LIST) - 1, i + random.choice([-2, -1, 1, 2])))]
        # enforce <=4 types by merging
        while len(set(deck.values())) > 4:
            z = random.choice(ZLIST)
            deck[z] = random.choice(list(set(deck.values()) - {deck[z]}))
        return deck, chord


def run(seed=0, iters=30, start=None, verbose=True, **kw):
    random.seed(seed)
    f = Fast(5.0)
    o = Opt(f, **kw)
    if start is None:
        deck = {z: 'D22-36/7-4' for z in ZLIST}
        chord = {c: 'PL3x3/8' for c in CLIST}
    else:
        deck, chord = start
    deck, chord, cur = o.descend(deck, chord, verbose=verbose)
    best = (cur, deck, chord)
    print('initial descent', cur, o.nevals, flush=True)
    for it in range(iters):
        d2, c2 = o.perturb(best[1], best[2], k=random.choice([2, 3, 4]))
        d2, c2, j = o.descend(d2, c2)
        if j[0] < best[0][0] - 1e-6:
            best = (j, d2, c2)
            print('it %d improved J=%.0f cost=%.0f viol=%.4f evals=%d' % (it, *j, o.nevals), flush=True)
    return best, o


if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    iters = int(sys.argv[2]) if len(sys.argv) > 2 else 20
    t = time.time()
    best, o = run(seed, iters)
    print('time', time.time() - t, 'evals', o.nevals)
    print(json.dumps(dict(J=best[0], deck=best[1], chord=best[2]), indent=1))
    json.dump(dict(J=best[0], deck=best[1], chord=best[2]), open('/filesystem/work/best_seed%d.json' % seed, 'w'), indent=1)

