import numpy as np, random, json, sys, time, os
from fasteval import *

LAM = 1.0e6


class Opt:
    def __init__(self, f, **kw):
        self.f = f
        self.kw = kw
        self.cache = {}
        self.nevals = 0

    def key(self, deck, chord):
        return tuple(deck[z] for z in ZLIST) + tuple(chord[c] for c in CLIST)

    def J(self, deck, chord):
        k = self.key(deck, chord)
        if k not in self.cache:
            if len(set(deck.values())) > 4:
                self.cache[k] = (1e12, 1e12, 1e6)
            else:
                o = self.f.evaluate(deck, chord, **self.kw)
                self.nevals += 1
                self.cache[k] = (o['total'] + LAM * o['viol'], o['total'], o['viol'])
        return self.cache[k]

    def neighbours(self, deck, chord):
        types = sorted(set(deck.values()))
        for z in ZLIST:
            for t in DECK_LIST:
                if t == deck[z]:
                    continue
                d2 = dict(deck); d2[z] = t
                if len(set(d2.values())) > 4:
                    continue
                yield d2, chord
        # global type replacement
        for t1 in types:
            for t2 in DECK_LIST:
                if t2 == t1:
                    continue
                d2 = {z: (t2 if deck[z] == t1 else deck[z]) for z in ZLIST}
                yield d2, chord
        for c in CLIST:
            i = SEC_LIST.index(chord[c])
            for di in (-2, -1, 1, 2):
                j = i + di
                if 0 <= j < len(SEC_LIST):
                    c2 = dict(chord); c2[c] = SEC_LIST[j]
                    yield deck, c2
        # pair moves: zone deck change + C-E2 change
        for z in ZLIST:
            i = DECK_LIST.index(deck[z])
            for t in types:
                if t == deck[z]:
                    continue
                for c in ('C-E2', 'K-E2'):
                    j = SEC_LIST.index(chord[c])
                    for dj in (-1, 1):
                        if 0 <= j + dj < len(SEC_LIST):
                            d2 = dict(deck); d2[z] = t
                            c2 = dict(chord); c2[c] = SEC_LIST[j + dj]
                            yield d2, c2

    def descend(self, deck, chord, verbose=False, first_improvement=True):
        cur = self.J(deck, chord)
        while True:
            best = None
            nb = list(self.neighbours(deck, chord))
            random.shuffle(nb)
            for d2, c2 in nb:
                j = self.J(d2, c2)
                if j[0] < cur[0] - 1e-6 and (best is None or j[0] < best[0][0]):
                    best = (j, d2, c2)
                    if first_improvement:
                        break
            if best is None:
                return deck, chord, cur
            cur, deck, chord = best
            if verbose:
                print('  J=%.0f cost=%.0f viol=%.4f' % cur, flush=True)

    def perturb(self, deck, chord, k=3):
        deck = dict(deck); chord = dict(chord)
        for _ in range(k):
            r = random.random()
            types = list(set(deck.values()))
            if r < 0.6:
                z = random.choice(ZLIST)
                if random.random() < 0.5:
                    deck[z] = random.choice(types)
                else:
                    i = DECK_LIST.index(deck[z])
                    deck[z] = DECK_LIST[max(0, min(len(DECK_LIST) - 1, i + random.choice([-4, -3, -2, -1, 1, 2, 3, 4])))]
            elif r < 0.75:
                t1 = random.choice(types)
                t2 = random.choice(DECK_LIST)
                deck = {z: (t2 if deck[z] == t1 else deck[z]) for z in ZLIST}
            else:
                c = random.choice(CLIST)
                i = SEC_LIST.index(chord[c])
                chord[c] = SEC_LIST[max(0, min(len(SEC_LIST) - 1, i + random.choice([-3, -2, -1, 1, 2, 3])))]
        while len(set(deck.values())) > 4:
            z = random.choice(ZLIST)
            deck[z] = random.choice(list(set(deck.values()) - {deck[z]}))
        return deck, chord


def run(seed, tmax, kw, starts, out):
    random.seed(seed)
    f = FastBand(5.0, embed_rule=kw.pop('embed_rule', 'B'))
    o = Opt(f, **kw)
    best = None
    t0 = time.time()
    for (deck, chord) in starts:
        d, c, j = o.descend(dict(deck), dict(chord), first_improvement=False)
        print('start ->', '%.0f %.0f %.4f' % j, flush=True)
        if best is None or j[0] < best[0][0]:
            best = (j, d, c)
    it = 0
    while time.time() - t0 < tmax:
        it += 1
