import numpy as np, itertools, json, sys, time, random
from fasteval import *

KW = dict(vm=0.97, dm=0.536, bm=0.97, cm=0.95, vfac=1.03)
LAM = 1.0e6


class Ev:
    def __init__(self):
        self.f = FastBand(5.0, embed_rule='A')
        self.cache = {}
        self.n = 0

    def J(self, deck, chord):
        k = tuple(deck[z] for z in ZLIST) + tuple(chord[c] for c in CLIST)
        if k not in self.cache:
            o = self.f.evaluate(deck, chord, **KW)
            self.n += 1
            self.cache[k] = (o['total'] + LAM * o['viol'], o['total'], o['viol'])
        return self.cache[k]


def inner(ev, pal, start_chord, start_deck=None):
    pal = sorted(pal, key=lambda t: DECKS[t]['cost'])
    if start_deck is None:
        deck = {z: pal[0] for z in ZLIST}
    else:
        deck = dict(start_deck)
    chord = dict(start_chord)
    cur = ev.J(deck, chord)
    # greedy upgrades until feasible
    it = 0
    while cur[2] > 0 and it < 40:
        it += 1
        best = None
        for z in ZLIST:
            i = pal.index(deck[z])
            for j in range(i + 1, len(pal)):
                d2 = dict(deck); d2[z] = pal[j]
                jj = ev.J(d2, chord)
                dv = cur[2] - jj[2]
                dc = jj[1] - cur[1] + 1.0
                if dv > 1e-9:
                    score = dv / dc
                    if best is None or score > best[0]:
                        best = (score, d2, jj)
        for c in CLIST:
            i = SEC_LIST.index(chord[c])
            if i + 1 < len(SEC_LIST):
                c2 = dict(chord); c2[c] = SEC_LIST[i + 1]
                jj = ev.J(deck, c2)
                dv = cur[2] - jj[2]
                dc = jj[1] - cur[1] + 1.0
                if dv > 1e-9:
                    score = dv / dc
                    if best is None or score > best[0]:
                        best = (score, None, jj, c2)
        if best is None:
            break
        if best[1] is None:
            chord = best[3]
        else:
            deck = best[1]
        cur = best[2]
    # descent: single moves within palette + chord moves + pair swaps
    improved = True
    while improved:
        improved = False
        moves = []
        for z in ZLIST:
            for t in pal:
                if t != deck[z]:
                    d2 = dict(deck); d2[z] = t
                    moves.append((d2, chord))
        for c in CLIST:
            i = SEC_LIST.index(chord[c])
            for dj in (-2, -1, 1, 2):
                if 0 <= i + dj < len(SEC_LIST):
                    c2 = dict(chord); c2[c] = SEC_LIST[i + dj]
                    moves.append((deck, c2))
        # pair: downgrade one zone, upgrade another
        for z1 in ZLIST:
            i1 = pal.index(deck[z1])
            if i1 == 0:
                continue
            for z2 in ZLIST:
                if z2 == z1:
                    continue
                i2 = pal.index(deck[z2])
                if i2 + 1 < len(pal):
                    d2 = dict(deck); d2[z1] = pal[i1 - 1]; d2[z2] = pal[i2 + 1]
                    moves.append((d2, chord))
        for d2, c2 in moves:
            jj = ev.J(d2, c2)
            if jj[0] < cur[0] - 1e-6:
                deck, chord, cur = d2, c2, jj
                improved = True
                break
    return cur, deck, chord


if __name__ == '__main__':
    tmax = float(sys.argv[1]) if len(sys.argv) > 1 else 3000
    ev = Ev()
    base = 'D22-36/4-2'
    others = [t for t in DECK_LIST if t != base]
    pals = [tuple([base] + list(c)) for c in itertools.combinations(others, 3)]
    random.seed(0)
    random.shuffle(pals)
    best_chord = json.load(open('/filesystem/work/opt2_s2.json'))['chord'] if False else None
    ch0 = {c: 'PL3x3/8' for c in CLIST}
    results = []
    t0 = time.time()
    best = None
    for k, pal in enumerate(pals):
        cur, deck, chord = inner(ev, pal, ch0)
        results.append((cur[0], cur[1], cur[2], pal, deck, chord))
        if cur[2] == 0 and (best is None or cur[0] < best[0]):
            best = (cur[0], deck, chord)
            print('t=%.0f k=%d pal=%s J=%.0f evals=%d' % (time.time() - t0, k, pal, cur[0], ev.n), flush=True)
            json.dump(dict(J=[cur[0], cur[1], cur[2]], deck=deck, chord=chord), open('/filesystem/work/pal_best.json', 'w'), indent=1)
        if time.time() - t0 > tmax:
            break
    results.sort(key=lambda r: r[0])
    json.dump([dict(J=r[0], pal=r[3], deck=r[4], chord=r[5]) for r in results[:40]],
              open('/filesystem/work/pal_top.json', 'w'), indent=1)
    print('done', len(results), 'palettes', ev.n, 'evals', time.time() - t0)
    for r in results[:10]:
        print('%.0f %s' % (r[0], r[3]))

"""Re-analyse the submitted design from the zip only and compare reported quantities (tolerance 7.5% or abs)."""
import zipfile, io, sys, math, collections
import numpy as np, openpyxl
from a2data import *
from a2model import A2

ZIP = BASE + '/output/submission.zip'


def tol_ok(rep, ref, absval):
    return abs(rep - ref) <= max(0.075 * abs(ref), absval)


def main():
    z = zipfile.ZipFile(ZIP)
    names = z.namelist()
    assert sorted(names) == sorted(['lateral_schedule.xlsx', 'diaphragm_plan.dxf', 'constraint_register.xlsx',
                                    'calculations.pdf', 'design_basis.md']), names
    wb = openpyxl.load_workbook(io.BytesIO(z.read('lateral_schedule.xlsx')))
    sh = {ws.title: list(ws.iter_rows(values_only=True)) for ws in wb.worksheets}
    for t, rows in sh.items():
        for r in rows:
            for c in r:
                assert c is not None and c != '' and str(c).upper() not in ('TBD', 'N/A'), (t, r)
    deck = {r[0]: r[1] for r in sh['DeckZones'][1:]}
    chord = {r[0]: r[1] for r in sh['ChordSchedule'][1:]}
    a = A2(5.0)
    a.setup(deck, chord)
    res = {sc: a.run(sc) for sc in SCENARIOS}
    bad = collections.Counter()
    nchk = collections.Counter()
    # DeckZones
    for r in sh['DeckZones'][1:]:
        zid, code, G, cap, area, cost = r
        dk = DECKS[code]
        assert abs(G - dk['G'] * SPAN_ADJ.get(zid, 1.0)) < 0.01, r
        assert abs(cap - dk['nominal'] / 2.35) < 0.1, r
        assert abs(cost - area * dk['cost']) < 0.05, r
        vmax = max(rr['zone_vmax'][zid] for rr in res.values())
        if vmax > cap:
            print('ZONE OVERSTRESS', zid, vmax, cap)
    assert len(set(deck.values())) <= 4
    # ShearWalls
    for sc, ln, w, R in sh['ShearWalls'][1:]:
        rr = res[sc]
        nchk['SW'] += 2
        if not tol_ok(w, abs(rr['info']['line_load'][ln]) * 1000, 25):
            bad['SW_w'] += 1
        if not tol_ok(R, abs(rr['reaction'][ln]), 2):
            bad['SW_R'] += 1
    for sc, ln, fr, v in sh['Diaphragm'][1:]:
        vals, els = res[sc]['stations'][(ln, fr)]
        nchk['D'] += 1
        if not tol_ok(v, vals[0], 25):
            bad['D'] += 1
            print('  station mismatch', sc, ln, fr, v, vals)
    for sc, cid, f in sh['Chords'][1:]:
        nchk['C'] += 1
        if not tol_ok(f, res[sc]['chord'][cid], 2):
            bad['C'] += 1
    for sc, ax, d in sh['Drift'][1:]:
        nchk['Dr'] += 1
        if not tol_ok(d, res[sc]['defl'][ax], 0.05):
            bad['Dr'] += 1
        if d > 0.55:
            print('DEFLECTION EXCEEDED', sc, ax, d)
    # chords capacity
    for cid, sec in chord.items():
        s = CHORD_SECTIONS[sec]
        for sc, rr in res.items():
            bf = rr['bar_forces'][cid]
            if bf.max() > s['T'] or -bf.min() > s['C']:
                print('CHORD OVERSTRESS', cid, sc)
    # piers / panels
    piers = sh['Piers'][1:]
    pan_emb = {}
    pan_td = {}
    for r in piers:
        pid, panel, line, s0, s1, w, t, top, k, emb, td = r
        pan_emb[panel] = emb
        pan_td[panel] = td
        kk = pier_k(s1 - s0, t)
        assert abs(kk - k) < 0.01, r
    assert len(piers) == len(PIERS)
    for p in PANELS:
        mk = p['mark']
        V = 0
        for sc, rr in res.items():
            v = abs(sum(f for pr, f in zip(PIERS, rr['pier_force']) if pr['panel'] == mk))
            V = max(V, v)
        L = p['L']
        req = max(2, math.ceil(L / 8 - 1e-9), math.ceil(V / 4.2 - 1e-9))
        if pan_emb[mk] < req:
            print('EMBEDS SHORT', mk, pan_emb[mk], req)
        if V > 1.4 * L:
            print('B1 EXCEEDED', mk, V, 1.4 * L)
        W = 0.15 * L * p['top'] * p['t_in'] / 12
        MR = 0.6 * W * L / 2 + (88 * L if pan_td[mk] == 'yes' else 0)
        if MR < V * 28:
            print('STABILITY FAIL', mk, V, MR)
    # cost
    tot = sum(r[3] for r in sh['Cost'][1:])
    dz = sum(r[5] for r in sh['DeckZones'][1:])
    cz = sum(r[3] for r in sh['ChordSchedule'][1:])
    nemb = sum(pan_emb.values())
    ntd = sum(1 for v in pan_td.values() if v == 'yes')
    calc = dz + cz + nemb * 185 + ntd * 2450
    print('cost sheet total %.2f  recomputed %.2f' % (tot, calc))
    # convergence
    conv = sh['Convergence'][1:]
    print('convergence rows', conv)
    print('checks', dict(nchk), 'mismatches', dict(bad))


if __name__ == '__main__':
    main()

